INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch07$PT159-S1-Q3$batch07$, 159, 1, 3, $batch07$Agree/Disagree$batch07$, $batch07$Hernandez: Celebrities’ public pronouncements can warp a debate because people grant more weight to celebrities’ opinions than to ordinary people’s. For that reason, celebrities should avoid talking publicly about controversial issues on which they have no expertise. Liu: But celebrities are full members of their communities. It is not their fault if people give their opinions more credence than they should. So it is absurd that they should not feel free to join controversial debates.$batch07$, $batch07$Hernandez and Liu disagree with each other about which one of the following?$batch07$, $batch07$B$batch07$, true, $batch07$Batch 07; question text from local bank.$batch07$ FROM lr_sections s WHERE s.preptest=159 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT159-S1-Q3$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$A$batch07$, $batch07$People grant more weight to celebrities’ opinions than to ordinary people’s.$batch07$, $batch07$Both Agree$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT159-S1-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$A$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$B$batch07$, $batch07$Celebrities should avoid talking publicly about controversial issues on which they have no expertise.$batch07$, $batch07$Correct$batch07$, true FROM lr_questions q WHERE q.qid=$batch07$PT159-S1-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$B$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$C$batch07$, $batch07$Celebrities’ pronouncements on controversial issues can warp debates on those issues.$batch07$, $batch07$Half Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT159-S1-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$C$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$D$batch07$, $batch07$The public should disregard what celebrities say about controversial issues.$batch07$, $batch07$Out of Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT159-S1-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$D$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch07$E$batch07$, $batch07$Celebrities are responsible for the fact that people give their opinions more credence than they should.$batch07$, $batch07$Half Scope$batch07$, false FROM lr_questions q WHERE q.qid=$batch07$PT159-S1-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch07$E$batch07$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT159-S1-Q3$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Hernandez's Position$batch07$, $batch07$People give celebrities' opinions too much weight, so celebrities can warp a debate. So they should avoid talking publicly about controversial issues they know nothing about.$batch07$), (1, $batch07$Liu's Position$batch07$, $batch07$Celebrities are full members of their communities. It's not their fault people overrate their opinions. So it's absurd to say they shouldn't feel free to join debates.$batch07$), (2, $batch07$Evaluate$batch07$, $batch07$Liu concedes the fact: people give celebrities "more credence than they should". Liu disagrees with what Hernandez wants to *do* about it. Hernandez: they should stay out. Liu: they should feel free to join.$batch07$), (3, $batch07$Goal$batch07$, $batch07$Whether celebrities should avoid speaking publicly on controversial issues outside their expertise.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT159-S1-Q3$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$Hernandez says it, and Liu concedes it: people give celebrities' opinions "more credence than they should".$batch07$), ($batch07$B$batch07$, $batch07$Hernandez says they should avoid these debates. Liu says it's "absurd that they should not feel free to join" them.$batch07$), ($batch07$C$batch07$, $batch07$Hernandez says celebrities can warp debates. Liu never denies it; Liu just says it isn't their fault.$batch07$), ($batch07$D$batch07$, $batch07$Neither says what the public should do with celebrities' opinions.$batch07$), ($batch07$E$batch07$, $batch07$Liu says it's not their fault. Hernandez never blames celebrities. Telling them to stay out of debates is not the same as saying they caused the problem.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT159-S1-Q3$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
